appsmith.onReady(function () {
  var initialized = false;
  var SIGNIFICANT_CHANGE_PCT = 5;
  function byId(id) {
    return document.getElementById(id);
  }
  function escapeHtml(value) {
    return String(value === null || value === undefined ? '' : value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
  }
  function toNumber(value) {
    if (value === null || value === undefined || value === '') {
      return null;
    }
    var number = Number(value);
    return Number.isFinite(number) ? number : null;
  }
  function formatNumber(value, maximumFractionDigits) {
    var number = toNumber(value);
    if (number === null) {
      return '—';
    }
    return new Intl.NumberFormat('es-MX', {
      maximumFractionDigits: maximumFractionDigits === undefined ? 2 : maximumFractionDigits
    }).format(number);
  }
  function formatInteger(value) {
    var number = toNumber(value);
    if (number === null) {
      return '—';
    }
    return new Intl.NumberFormat('es-MX', {
      maximumFractionDigits: 0
    }).format(number);
  }
  function formatPct(value) {
    var number = toNumber(value);
    if (number === null) {
      return '—';
    }
    return (number > 0 ? '+' : '') + formatNumber(number, 2) + '%';
  }
  function trendClass(value) {
    var number = toNumber(value);
    if (number === null) {
      return 'neutral';
    }
    if (number > 0) {
      return 'positive';
    }
    if (number < 0) {
      return 'negative';
    }
    return 'neutral';
  }
  function isSignificantPositive(value) {
    var number = toNumber(value);
    return number !== null && number >= SIGNIFICANT_CHANGE_PCT;
  }
  function isSignificantNegative(value) {
    var number = toNumber(value);
    return number !== null && number <= -SIGNIFICANT_CHANGE_PCT;
  }
  function platformLabel(value) {
    var map = {
      facebook: 'Facebook',
      instagram: 'Instagram',
      tiktok: 'TikTok',
      threads: 'Threads',
      all: 'Todas'
    };
