      return;
    }
    setText('generatedAt', 'Actualizado: ' + date.toLocaleString('es-MX', {
      dateStyle: 'short',
      timeStyle: 'short'
    }));
  }
  function syncControls(model) {
    var period = byId('periodSelect');
    var platform = byId('platformSelect');
    if (period) {
      period.value = String(model && model.periodDays ? model.periodDays : 30);
    }
    if (platform) {
      platform.value = String(model && model.platform ? model.platform : 'all');
    }
    renderQuerySelect(model);
  }
  function render(model) {
    model = model || {};
    syncControls(model);
    var runtime = getRuntime(model);
    var meta = runtime.meta || {};
    if (meta.loading === true) {
      setLoading();
      return;
    }
    if (meta.error) {
      setError(meta.error);
      return;
    }
    if (meta.empty === true || runtime.palancas.length === 0) {
      setEmpty();
      return;
    }
    var overall = findOverall(runtime.palancas);
    if (!overall) {
      setEmpty();
      return;
    }
    var platformRows = getPlatformRows(runtime.palancas);
    var recommendations = getRecommendations(runtime);
    setReady();
    buildStatus(overall, platformRows);
    renderAIGuidance(runtime, model, recommendations);
    renderInsights(overall, runtime.formatos, platformRows, runtime.evidencias, recommendations);
    renderActions(recommendations, meta);
    renderPlatforms(platformRows);
    renderFormats(runtime.formatos);
    renderEvidence(runtime.evidencias);
    renderMethodology(recommendations);
    renderGeneratedAt(meta.generatedAt);
  }
  async function requestReload(modelChanges) {
    try {
      setLoading();
      var changes = modelChanges || {};
      if (Object.keys(changes).length > 0) {
        await appsmith.updateModel(changes);
      }
      appsmith.triggerEvent('onRefresh');
    } catch (error) {
      setError(error && error.message ? error.message : String(error));
    }
  }
  function bindEvents() {
    if (initialized) {
      return;
    }
    initialized = true;
    var period = byId('periodSelect');
    var platform = byId('platformSelect');
    var query = byId('querySelect');
    var refresh = byId('refreshButton');
    var evidenceContainer = byId('evidenceCards');
    if (period) {
      period.addEventListener('change', function (event) {
        requestReload({
          periodDays: Number(event.target.value)
        });
      });
    }
    if (platform) {
      platform.addEventListener('change', function (event) {
        requestReload({
          platform: String(event.target.value)
        });
      });
    }
    if (query) {
      query.addEventListener('change', function (event) {
        var selectedId = String(event.target.value || '').trim();
        var selectedOption = event.target.options[event.target.selectedIndex];
        var selectedName = selectedOption ? String(selectedOption.textContent || '').trim() : '';
        if (!selectedId) {
          return;
        }
        requestReload({
          selectedQueryId: selectedId,
          selectedQueryName: selectedName
        });
      });
    }
    if (refresh) {
      refresh.addEventListener('click', function () {
        requestReload({});
      });
    }
    if (evidenceContainer) {
      evidenceContainer.addEventListener('click', function (event) {
        var button = event.target.closest('.evidence-link[data-post-url]');
        if (!button) {
          return;
        }
        var url = String(button.getAttribute('data-post-url') || '').trim();
        if (!url) {
          return;
        }
        appsmith.triggerEvent('onOpenPost', {
          url: url
        });
      });
    }
  }
  bindEvents();
  render(appsmith.model || {});
  appsmith.onModelChange(function (newModel) {
    render(newModel || {});
  });
});

