appsmith.onReady(function () {
  var initialized = false;
  var SIGNIFICANT_CHANGE_PCT = 5;

  function byId(id) {
    return document.getElementById(id);
  }

  function escapeHtml(value) {
    return String(
      value === null ||
      value === undefined
        ? ''
        : value
    )
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function toNumber(value) {
    if (
      value === null ||
      value === undefined ||
      value === ''
    ) {
      return null;
    }

    var number =
      Number(value);

    return Number.isFinite(number)
      ? number
      : null;
  }

  function formatNumber(
    value,
    maximumFractionDigits
  ) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    return new Intl.NumberFormat(
      'es-MX',
      {
        maximumFractionDigits:
          maximumFractionDigits === undefined
            ? 2
            : maximumFractionDigits
      }
    ).format(number);
  }

  function formatInteger(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    return new Intl.NumberFormat(
      'es-MX',
      {
        maximumFractionDigits: 0
      }
    ).format(number);
  }

  function formatPct(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    return (
      (
        number > 0
          ? '+'
          : ''
      ) +
      formatNumber(
        number,
        2
      ) +
      '%'
    );
  }

  function trendClass(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return 'neutral';
    }

    if (number > 0) {
      return 'positive';
    }

    if (number < 0) {
      return 'negative';
    }

    return 'neutral';
  }

  function isSignificantPositive(value) {
    var number =
      toNumber(value);

    return (
      number !== null &&
      number >=
        SIGNIFICANT_CHANGE_PCT
    );
  }

  function isSignificantNegative(value) {
    var number =
      toNumber(value);

    return (
      number !== null &&
      number <=
        -SIGNIFICANT_CHANGE_PCT
    );
  }

  function platformLabel(value) {
    var map = {
      facebook: 'Facebook',
      instagram: 'Instagram',
      tiktok: 'TikTok',
      threads: 'Threads',
      all: 'Todas'
    };

    var key =
      String(value || '')
        .toLowerCase();

    return (
      map[key] ||
      String(value || '')
    );
  }

  function formatLabel(value) {
    var map = {
      video: 'Video',
      carousel: 'Carrusel',
      image: 'Imagen',
      text: 'Texto',
      sin_clasificar: 'Sin clasificar'
    };

    var key =
      String(value || '')
        .toLowerCase();

    return (
      map[key] ||
      String(value || '')
    );
  }

  function shortText(
    value,
    maxLength
  ) {
    var text =
      String(value || '')
        .replace(/\s+/g, ' ')
        .trim();

    if (
      text.length <=
      maxLength
    ) {
      return text;
    }

    return (
      text
        .slice(
          0,
          maxLength - 1
        )
        .trim() +
      '…'
    );
  }

  function getRuntime(model) {
    var runtime =
      model &&
      model.runtime
        ? model.runtime
        : {};

    return {
      queries:
        Array.isArray(
          runtime.queries
        )
          ? runtime.queries
          : [],

      estado:
        runtime.estado ||
        null,

      palancas:
        Array.isArray(
          runtime.palancas
        )
          ? runtime.palancas
          : [],

      formatos:
        Array.isArray(
          runtime.formatos
        )
          ? runtime.formatos
          : [],

      evidencias:
        Array.isArray(
          runtime.evidencias
        )
          ? runtime.evidencias
          : [],

      insight:
        runtime.insight ||
        (
          model &&
          model.insight
            ? model.insight
            : null
        ),

      meta:
        runtime.meta || {
          loading: true,
          empty: false,
          error: '',
          generatedAt: null,
          insightLoading: false,
          insightError: '',
          insightGeneratedAt: null
        }
    };
  }

  function getRecommendations(
    runtime
  ) {
    var insight =
      runtime &&
      runtime.insight &&
      typeof runtime.insight ===
        'object'
        ? runtime.insight
        : null;

    if (
      !insight ||
      !insight.recommendations ||
      typeof insight.recommendations !==
        'object' ||
      Array.isArray(
        insight.recommendations
      )
    ) {
      return null;
    }

    return insight.recommendations;
  }

  function getQueries(model) {
    if (
      model &&
      Array.isArray(
        model.queries
      ) &&
      model.queries.length > 0
    ) {
      return model.queries;
    }

    return getRuntime(
      model
    ).queries;
  }

  function findOverall(rows) {
    if (
      !Array.isArray(rows)
    ) {
      return null;
    }

    for (
      var i = 0;
      i < rows.length;
      i++
    ) {
      if (
        String(
          rows[i].platform || ''
        ).toLowerCase() ===
        'all'
      ) {
        return rows[i];
      }
    }

    return null;
  }

  function getPlatformRows(rows) {
    return (
      Array.isArray(rows)
        ? rows.filter(
            function (row) {
              return (
                String(
                  row.platform || ''
                ).toLowerCase() !==
                'all'
              );
            }
          )
        : []
    );
  }

  function setText(
    id,
    value
  ) {
    var element =
      byId(id);

    if (!element) {
      return;
    }

    element.textContent =
      value === null ||
      value === undefined ||
      value === ''
        ? '—'
        : String(value);
  }

  function setTrend(
    id,
    value
  ) {
    var element =
      byId(id);

    if (!element) {
      return;
    }

    var className =
      trendClass(value);

    element.className =
      id ===
      'engagementTrend'
        ? (
            'trend-pill ' +
            className
          )
        : (
            'mini-kpi-change ' +
            className
          );

    element.textContent =
      formatPct(value);
  }

  function setLoading() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.remove(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }
  }

  function setError(message) {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.remove(
        'hidden'
      );
    }

    setText(
      'errorMessage',
      message
    );
  }

  function setEmpty() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.remove(
        'hidden'
      );
    }
  }

  function setReady() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.remove(
        'hidden'
      );
    }
  }

  function renderQuerySelect(
    model
  ) {
    var select =
      byId('querySelect');

    if (!select) {
      return;
    }

    var queries =
      getQueries(model);

    if (
      !Array.isArray(
        queries
      ) ||
      queries.length === 0
    ) {
      return;
    }

    var selectedQueryId =
      String(
        model &&
        model.selectedQueryId
          ? model.selectedQueryId
          : ''
      ).trim();

    select.innerHTML =
      queries
        .map(
          function (query) {
            var id =
              String(
                query &&
                query.id
                  ? query.id
                  : ''
              ).trim();

            var name =
              String(
                query &&
                query.name
                  ? query.name
                  : ''
              ).trim();

            return (
              '<option value="' +
                escapeHtml(id) +
              '">' +
                escapeHtml(name) +
              '</option>'
            );
          }
        )
        .join('');

    var selectedExists =
      queries.some(
        function (query) {
          return (
            String(
              query &&
              query.id
                ? query.id
                : ''
            ).trim() ===
            selectedQueryId
          );
        }
      );

    select.value =
      selectedExists
        ? selectedQueryId
        : String(
            queries[0].id ||
            ''
          );
  }

  function buildStatus(
    overall,
    platformRows
  ) {
    if (!overall) {
      return;
    }

    var current =
      toNumber(
        overall
          .current_engagement_per_post
      );

    var previous =
      toNumber(
        overall
          .previous_engagement_per_post
      );

    var change =
      toNumber(
        overall
          .engagement_per_post_change_pct
      );

    var days =
      toNumber(
        overall.comparison_days
      );

    setText(
      'engagementValue',
      formatNumber(
        current,
        2
      )
    );

    setTrend(
      'engagementTrend',
      change
    );

    setText(
      'currentPosts',
      formatInteger(
        overall.current_posts
      )
    );

    setTrend(
      'postsTrend',
      overall
        .publishing_change_pct
    );

    setText(
      'likesPerPost',
      formatNumber(
        overall
          .current_likes_per_post,
        2
      )
    );

    setTrend(
      'likesTrend',
      overall
        .likes_per_post_change_pct
    );

    setText(
      'commentsPerPost',
      formatNumber(
        overall
          .current_comments_per_post,
        2
      )
    );

    setTrend(
      'commentsTrend',
      overall
        .comments_per_post_change_pct
    );

    var comparablePlatforms =
      platformRows.filter(
        function (row) {
          return (
            toNumber(
              row.current_posts
            ) > 0 &&
            toNumber(
              row.previous_posts
            ) > 0
          );
        }
      ).length;

    setText(
      'comparablePlatforms',
      comparablePlatforms
    );

    if (days !== null) {
      setText(
        'comparisonBadge',
        (
          days +
          ' días vs ' +
          days +
          ' días'
        )
      );

      setText(
        'comparisonPeriod',
        (
          'últimos ' +
          days +
          ' días frente a los ' +
          days +
          ' días anteriores'
        )
      );

    } else {
      setText(
        'comparisonBadge',
        'Sin ventana comparable'
      );

      setText(
        'comparisonPeriod',
        'sin histórico comparable'
      );
    }

    var headline =
      'El engagement se mantiene sin un cambio concluyente';

    if (
      isSignificantNegative(
        change
      )
    ) {
      headline =
        'El engagement por publicación está por debajo de la ventana anterior';

    } else if (
      isSignificantPositive(
        change
      )
    ) {
      headline =
        'El engagement por publicación está por encima de la ventana anterior';
    }

    setText(
      'statusHeadline',
      headline
    );

    var explanation =
      'Aún no existe una comparación suficiente para describir la variación reciente.';

    if (
      current !== null &&
      previous !== null
    ) {
      explanation =
        (
          'Cada publicación registra ' +
          formatNumber(
            current,
            2
          ) +
          ' likes + comentarios, frente a ' +
          formatNumber(
            previous,
            2
          ) +
          ' en la ventana anterior.'
        );
    }

    setText(
      'statusExplanation',
      explanation
    );
  }

  function renderAIGuidance(
    runtime,
    model,
    recommendations
  ) {
    var meta =
      runtime &&
      runtime.meta
        ? runtime.meta
        : {};

    var periodDays =
      toNumber(
        model &&
        model.periodDays
      );

    var selectedPlatform =
      platformLabel(
        model &&
        model.platform
          ? model.platform
          : 'all'
      );

    var badgeParts = [
      'IA'
    ];

    if (
      periodDays !== null
    ) {
      badgeParts.push(
        formatInteger(
          periodDays
        ) +
        ' días'
      );
    }

    badgeParts.push(
      selectedPlatform
    );

    setText(
      'insightBadge',
      badgeParts.join(
        ' · '
      )
    );

    if (!recommendations) {
      if (
        meta.insightLoading ===
        true
      ) {
        setText(
          'insightHeadline',
          'Preparando orientación…'
        );

        setText(
          'insightSummary',
          'El diagnóstico cuantitativo ya está disponible. Las recomendaciones se están generando con la evidencia de la consulta seleccionada.'
        );

        setText(
          'insightExplanation',
          'El resto del análisis permanece disponible mientras termina la generación.'
        );

        return;
      }

      if (
        meta.insightError
      ) {
        setText(
          'insightHeadline',
          'Orientación IA no disponible'
        );

        setText(
          'insightSummary',
          meta.insightError
        );

        setText(
          'insightExplanation',
          'El análisis determinístico permanece disponible y no depende de esta recomendación.'
        );

        return;
      }

      setText(
        'insightHeadline',
        'Sin orientación IA disponible'
      );

      setText(
        'insightSummary',
        'No hay una recomendación generada para la combinación actual de consulta, periodo y plataforma.'
      );

      setText(
        'insightExplanation',
        'Actualiza el análisis para solicitar una recomendación basada en la evidencia disponible.'
      );

      return;
    }

    var state =
      recommendations.state &&
      typeof recommendations.state ===
        'object' &&
      !Array.isArray(
        recommendations.state
      )
        ? recommendations.state
        : {};

    setText(
      'insightHeadline',
      state.headline ||
      'Orientación basada en evidencia'
    );

    setText(
      'insightSummary',
      recommendations.summary ||
      '—'
    );

    setText(
      'insightExplanation',
      state.explanation ||
      '—'
    );
  }

  function insightItem(
    title,
    description,
    metric
  ) {
    return (
      '<div class="insight-item">' +
        '<span class="insight-bullet"></span>' +

        '<div class="insight-copy">' +
          '<strong>' +
            escapeHtml(title) +
          '</strong>' +

          '<span>' +
            escapeHtml(
              description
            ) +
          '</span>' +
        '</div>' +

        '<span class="insight-metric">' +
          escapeHtml(
            metric || ''
          ) +
        '</span>' +
      '</div>'
    );
  }

  function buildFallbackDrivers(
    overall,
    formats,
    platformRows,
    evidence
  ) {
    var drivers = [];

    var positiveFormats =
      formats
        .filter(
          function (row) {
            return (
              String(
                row.platform ||
                ''
              ).toLowerCase() !==
                'all' &&
              toNumber(
                row.current_posts
              ) >= 2 &&
              isSignificantPositive(
                row
                  .engagement_per_post_change_pct
              )
            );
          }
        )
        .sort(
          function (
            a,
            b
          ) {
            return (
              toNumber(
                b
                  .engagement_per_post_change_pct
              ) -
              toNumber(
                a
                  .engagement_per_post_change_pct
              )
            );
          }
        );

    if (
      positiveFormats.length >
      0
    ) {
      var format =
        positiveFormats[0];

      drivers.push({
        title:
          (
            formatLabel(
              format.post_type
            ) +
            ' en ' +
            platformLabel(
              format.platform
            )
          ),

        description:
          'El formato muestra una variación positiva frente a la ventana comparable.',

        metric:
          formatPct(
            format
              .engagement_per_post_change_pct
          )
      });
    }

    if (overall) {
      var likesChange =
        toNumber(
          overall
            .likes_per_post_change_pct
        );

      if (
        isSignificantPositive(
          likesChange
        )
      ) {
        drivers.push({
          title:
            'Más likes por publicación',

          description:
            'Los likes por publicación superan la ventana comparable anterior.',

          metric:
            formatPct(
              likesChange
            )
        });
      }
    }

    if (
      evidence.length > 0 &&
      drivers.length < 3
    ) {
      var bestPost =
        evidence
          .filter(
            function (row) {
              return (
                toNumber(
                  row
                    .vs_platform_avg_pct
                ) !== null
              );
            }
          )
          .sort(
            function (
              a,
              b
            ) {
              return (
                toNumber(
                  b
                    .vs_platform_avg_pct
                ) -
                toNumber(
                  a
                    .vs_platform_avg_pct
                )
              );
            }
          )[0];

      if (bestPost) {
        drivers.push({
          title:
            (
              'Una publicación destaca en ' +
              platformLabel(
                bestPost.platform
              )
            ),

          description:
            shortText(
              bestPost.content_text,
              96
            ),

          metric:
            (
              formatPct(
                bestPost
                  .vs_platform_avg_pct
              ) +
              ' vs promedio'
            )
        });
      }
    }

    if (
      drivers.length === 0
    ) {
      drivers.push({
        title:
          'Sin señal positiva concluyente',

        description:
          'La ventana actual todavía no muestra una mejora consistente frente a la anterior.',

        metric:
          ''
      });
    }

    return drivers.slice(
      0,
      3
    );
  }

  function buildFallbackFrictions(
    overall,
    platformRows
  ) {
    var frictions = [];

    if (!overall) {
      return frictions;
    }

    var overallChange =
      toNumber(
        overall
          .engagement_per_post_change_pct
      );

    var commentsChange =
      toNumber(
        overall
          .comments_per_post_change_pct
      );

    if (
      isSignificantNegative(
        overallChange
      )
    ) {
      frictions.push({
        title:
          'Menor engagement por publicación',

        description:
          'El promedio reciente de likes + comentarios por publicación está por debajo de la ventana anterior.',

        metric:
          formatPct(
            overallChange
          )
      });
    }

    if (
      isSignificantNegative(
        commentsChange
      )
    ) {
      frictions.push({
        title:
          'Menor nivel de comentarios',

        description:
          'Los comentarios por publicación muestran una reducción relevante en la ventana comparable.',

        metric:
          formatPct(
            commentsChange
          )
      });
    }

    var decliningPlatforms =
      platformRows
        .filter(
          function (row) {
            return (
              isSignificantNegative(
                row
                  .engagement_per_post_change_pct
              )
            );
          }
        )
        .sort(
          function (
            a,
            b
          ) {
            return (
              toNumber(
                a
                  .engagement_per_post_change_pct
              ) -
              toNumber(
                b
                  .engagement_per_post_change_pct
              )
            );
          }
        );

    if (
      decliningPlatforms.length >
        0 &&
      frictions.length < 3
    ) {
      var weakest =
        decliningPlatforms[0];

      frictions.push({
        title:
          (
            platformLabel(
              weakest.platform
            ) +
            ' presenta la mayor caída'
          ),

        description:
          'Es la variación negativa más relevante de engagement por publicación dentro de la comparación reciente.',

        metric:
          formatPct(
            weakest
              .engagement_per_post_change_pct
          )
      });
    }

    if (
      frictions.length === 0
    ) {
      frictions.push({
        title:
          'Sin deterioro relevante detectado',

        description:
          'Las señales comparables actuales no muestran variaciones negativas de al menos 5%.',

        metric:
          ''
      });
    }

    return frictions.slice(
      0,
      3
    );
  }

  function renderInsights(
    overall,
    formats,
    platformRows,
    evidence,
    recommendations
  ) {
    var drivers;
    var frictions;

    if (recommendations) {
      drivers =
        Array.isArray(
          recommendations.drivers
        )
          ? recommendations.drivers.map(
              function (item) {
                return {
                  title:
                    item &&
                    item.title
                      ? item.title
                      : 'Señal observada',

                  description:
                    item &&
                    item.evidence
                      ? item.evidence
                      : '',

                  metric: ''
                };
              }
            )
          : [];

      frictions =
        Array.isArray(
          recommendations.frictions
        )
          ? recommendations.frictions.map(
              function (item) {
                return {
                  title:
                    item &&
                    item.title
                      ? item.title
                      : 'Señal que requiere atención',

                  description:
                    item &&
                    item.evidence
                      ? item.evidence
                      : '',

                  metric: ''
                };
              }
            )
          : [];

      if (
        drivers.length === 0
      ) {
        drivers.push({
          title:
            'Sin palanca concluyente',

          description:
            'La evidencia disponible no permite señalar una palanca suficientemente respaldada para esta combinación de filtros.',

          metric:
            ''
        });
      }

      if (
        frictions.length === 0
      ) {
        frictions.push({
          title:
            'Sin fricción concluyente',

          description:
            'La evidencia disponible no identifica una fricción suficientemente respaldada para esta combinación de filtros.',

          metric:
            ''
        });
      }

    } else {
      drivers =
        buildFallbackDrivers(
          overall,
          formats,
          platformRows,
          evidence
        );

      frictions =
        buildFallbackFrictions(
          overall,
          platformRows
        );
    }

    var driversElement =
      byId('driversList');

    var frictionsElement =
      byId('frictionsList');

    if (driversElement) {
      driversElement.innerHTML =
        drivers
          .map(
            function (item) {
              return insightItem(
                item.title,
                item.description,
                item.metric
              );
            }
          )
          .join('');
    }

    if (frictionsElement) {
      frictionsElement.innerHTML =
        frictions
          .map(
            function (item) {
              return insightItem(
                item.title,
                item.description,
                item.metric
              );
            }
          )
          .join('');
    }
  }

  function renderActions(
    recommendations,
    meta
  ) {
    var element =
      byId('actionsList');

    if (!element) {
      return;
    }

    var actions = [];

    if (
      recommendations &&
      Array.isArray(
        recommendations.actions
      )
    ) {
      var opportunities =
        Array.isArray(
          recommendations.opportunities
        )
          ? recommendations.opportunities
          : [];

      actions =
        recommendations.actions.map(
          function (
            action,
            index
          ) {
            return {
              priority:
                toNumber(
                  action &&
                  action.priority
                ) ||
                index + 1,

              title:
                action &&
                action.title
                  ? action.title
                  : 'Acción prioritaria',

              description:
                action &&
                action.how
                  ? action.how
                  : '',

              evidence:
                action &&
                action.why
                  ? action.why
                  : '',

              opportunity:
                opportunities[
                  index
                ] ||
                null
            };
          }
        );
    }

    if (
      actions.length === 0
    ) {
      var loading =
        meta &&
        meta.insightLoading ===
          true;

      var insightError =
        meta &&
        meta.insightError
          ? String(
              meta.insightError
            )
          : '';

      element.style
        .gridTemplateColumns =
          'minmax(0, 1fr)';

      element.style.maxWidth =
        '900px';

      element.innerHTML =
        (
          '<article class="action-card">' +

            '<span class="action-number">' +
              '—' +
            '</span>' +

            '<h3>' +
              escapeHtml(
                loading
                  ? 'Generando recomendaciones…'
                  : (
                      insightError
                        ? 'Recomendaciones no disponibles'
                        : 'Sin acción prioritaria respaldada'
                    )
              ) +
            '</h3>' +

            '<p>' +
              escapeHtml(
                loading
                  ? 'La recomendación basada en evidencia se está preparando.'
                  : (
                      insightError
                        ? (
                            'El análisis determinístico sigue disponible. ' +
                            insightError
                          )
                        : 'La evidencia actual no permite proponer una acción prioritaria con suficiente respaldo.'
                    )
              ) +
            '</p>' +

          '</article>'
        );

      return;
    }

    element.style
      .gridTemplateColumns =
        actions.length === 1
          ? 'minmax(0, 1fr)'
          : (
              actions.length === 2
                ? 'repeat(2, minmax(0, 1fr))'
                : 'repeat(3, minmax(0, 1fr))'
            );

    element.style.maxWidth =
      actions.length === 1
        ? '900px'
        : '';

    element.innerHTML =
      actions
        .map(
          function (
            action,
            index
          ) {
            var opportunity =
              action.opportunity &&
              typeof action.opportunity ===
                'object'
                ? action.opportunity
                : null;

            var opportunityBlock =
              opportunity &&
              opportunity.next_test
                ? (
                    '<div class="action-evidence">' +
                      '<strong>Siguiente prueba: </strong>' +
                      escapeHtml(
                        opportunity.next_test
                      ) +
                    '</div>'
                  )
                : '';

            return (
              '<article class="action-card">' +

                '<span class="action-number">' +
                  escapeHtml(
                    action.priority ||
                    index + 1
                  ) +
                '</span>' +

                '<h3>' +
                  escapeHtml(
                    action.title
                  ) +
                '</h3>' +

                '<p>' +
                  escapeHtml(
                    action.description
                  ) +
                '</p>' +

                '<div class="action-evidence">' +
                  '<strong>Por qué: </strong>' +
                  escapeHtml(
                    action.evidence
                  ) +
                '</div>' +

                opportunityBlock +

              '</article>'
            );
          }
        )
        .join('');
  }

  function renderPlatforms(
    platformRows
