      return;
    }

    var rows =
      platformRows
        .slice()
        .sort(
          function (
            a,
            b
          ) {
            var rankA =
              toNumber(
                a
                  .engagement_per_post_rank
              );

            var rankB =
              toNumber(
                b
                  .engagement_per_post_rank
              );

            if (
              rankA === null
            ) {
              rankA = 999;
            }

            if (
              rankB === null
            ) {
              rankB = 999;
            }

            return (
              rankA -
              rankB
            );
          }
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="platform-card">' +
            '<span class="platform-name">' +
              'Sin datos comparables' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(
          function (row) {
            var change =
              toNumber(
                row
                  .engagement_per_post_change_pct
              );

            var rank =
              toNumber(
                row
                  .engagement_per_post_rank
              );

            return (
              '<article class="platform-card">' +

                '<div class="platform-card-head">' +

                  '<span class="platform-name">' +
                    escapeHtml(
                      platformLabel(
                        row.platform
                      )
                    ) +
                  '</span>' +

                  (
                    rank !== null
                      ? (
                          '<span class="platform-rank">' +
                            '#' +
                            escapeHtml(
                              rank
                            ) +
                            ' por engagement/post' +
                          '</span>'
                        )
                      : ''
                  ) +

                '</div>' +

                '<div class="platform-primary">' +

                  '<strong>' +
                    escapeHtml(
                      formatNumber(
                        row
                          .current_engagement_per_post,
