                      )
                    ) +
                  '</strong>' +

                  '<span>' +
                    'engagement / post' +
                  '</span>' +

                '</div>' +

                '<div class="platform-change ' +
                  escapeHtml(
                    trendClass(
                      change
                    )
                  ) +
                '">' +

                  escapeHtml(
                    formatPct(
                      change
                    )
                  ) +

                  ' vs ventana anterior' +

                '</div>' +

                '<div class="platform-meta">' +

                  '<div>' +
                    '<span>Aporte actual</span>' +
                    '<strong>' +
