      formats.filter(
        function (row) {
          return (
            String(
              row.platform || ''
            ).toLowerCase() !==
              'all' &&
            toNumber(
              row.current_posts
            ) > 0
          );
        }
      );

    var rows =
      specificRows.length > 0
        ? specificRows
        : formats.filter(
            function (row) {
              return (
                toNumber(
                  row.current_posts
                ) > 0
              );
            }
          );

    rows =
      rows
        .slice()
        .sort(
          function (
            a,
            b
          ) {
            return (
              (
                toNumber(
                  b
                    .current_engagement_per_post
                ) ||
                0
              ) -
              (
                toNumber(
                  a
                    .current_engagement_per_post
                ) ||
                0
              )
            );
          }
        )
        .slice(
          0,
          6
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="format-card">' +
            '<span class="format-name">' +
              'Sin formatos comparables' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(
          function (row) {
            return (
              '<article class="format-card">' +

                '<div class="format-card-head">' +

