                    escapeHtml(
                      formatLabel(
                        row.post_type
                      )
                    ) +
                  '</span>' +

                  '<span class="format-platform">' +
                    escapeHtml(
                      platformLabel(
                        row.platform
                      )
                    ) +
                  '</span>' +

