  function renderEvidence(
    evidence
  ) {
    var element =
      byId(
        'evidenceCards'
      );

    if (!element) {
      return;
    }

    var rows =
      evidence
        .slice()
        .sort(
          function (
            a,
            b
          ) {
            var platformCompare =
              String(
                a.platform ||
                ''
              ).localeCompare(
                String(
                  b.platform ||
                  ''
                )
              );

            if (
              platformCompare !==
              0
            ) {
              return platformCompare;
            }

            return (
              (
                toNumber(
                  a.platform_rank
                ) ||
                999
              ) -
              (
                toNumber(
                  b.platform_rank
                ) ||
                999
              )
            );
          }
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="evidence-card">' +
            '<span class="evidence-platform">' +
              'Sin evidencia disponible' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(
          function (row) {
            var url =
              String(
                row.post_url ||
