                    ) +
                    ' de la plataforma' +
                  '</span>' +

                '</div>' +

                '<span class="evidence-format">' +
                  escapeHtml(
                    formatLabel(
                      row.post_type
                    )
                  ) +
                '</span>' +

                '<p class="evidence-copy">' +
                  escapeHtml(
